def transform(grid):
    """
    Transform grid based on separator patterns (horizontal/vertical).

    Rule: Copy non-background pattern content from the data-source panel 
    to all other empty panels in the grid.
    """
    from collections import Counter
    g = [row[:] for row in grid]

    bg_counts = Counter(cell for row in g for cell in row)
    bg = max(bg_counts, key=bg_counts.get)
    nrows = len(g)
    ncols = len(g[0])

    def get_panels(seps, total_len):
        panels = []
        start = -1
        for idx in range(-1, total_len):
            if idx == -1:
                start = 0
            elif idx in seps:
                if start >= 0 and start < idx:
                    panels.append((start, idx - 1))
                start = idx + 1
        if start >= 0 and start < total_len:
            panels.append((start, total_len - 1))
        return panels

    # Detect horizontal separators (uniform row, not background color)
    horiz_seps = [r for r in range(nrows) 
                  if len({g[r][c] for c in range(ncols)}) == 1 and g[r][0] != bg]
    # Detect vertical separators (uniform column, not background color)
    vert_seps = [c for c in range(ncols) 
                 if len({g[r][c] for r in range(nrows)}) == 1 and g[0][c] != bg]

    # Case 1: Only vertical separators
    if vert_seps and not horiz_seps:
        vert_panels = get_panels(vert_seps, ncols)
        source_idx = next((idx for idx, (cs, ce) in enumerate(vert_panels) 
                          if any(g[r][c] != bg for r in range(nrows) for c in range(cs, ce + 1))), None)
        if source_idx is not None:
            source_cs, source_ce = vert_panels[source_idx]
            for target_idx, (target_cs, target_ce) in enumerate(vert_panels):
                if target_idx == source_idx:
                    continue
                if not any(g[r][c] != bg for r in range(nrows) for c in range(target_cs, target_ce + 1)):
                    for r in range(nrows):
                        for c in range(target_cs, target_ce + 1):
                            g[r][c] = g[r][source_cs + (c - target_cs)]
        return g

    # Case 2: Only horizontal separators
    elif horiz_seps and not vert_seps:
        horiz_panels = get_panels(horiz_seps, nrows)
        source_idx = next((idx for idx, (ps, pe) in enumerate(horiz_panels) 
                          if any(g[r][c] != bg for r in range(ps, pe + 1) for c in range(ncols))), None)
        if source_idx is not None:
            source_ps, source_pe = horiz_panels[source_idx]
            for target_idx, (target_ps, target_pe) in enumerate(horiz_panels):
                if target_idx == source_idx:
                    continue
                if not any(g[r][c] != bg for r in range(target_ps, target_pe + 1) for c in range(ncols)):
                    for r in range(target_ps, target_pe + 1):
                        g[r] = g[source_ps + (r - target_ps)][:]
        return g

    # Case 3: Both separators (3x3 grid of panels)
    elif horiz_seps and vert_seps:
        horiz_panels = get_panels(horiz_seps, nrows)
        vert_panels = get_panels(vert_seps, ncols)

        # Find panel with most non-background cells (source)
        source_h, source_v = None, None
        max_count = -1
        for hidx, (hp_start, hp_end) in enumerate(horiz_panels):
            for vidx, (vp_start, vp_end) in enumerate(vert_panels):
                count = sum(1 for r in range(hp_start, hp_end + 1) for c in range(vp_start, vp_end + 1) 
                           if g[r][c] != bg)
                if count > max_count:
                    max_count = count
                    source_h, source_v = hidx, vidx

        if source_h is not None and source_v is not None:
            h_start = horiz_panels[source_h][0]
            v_start = vert_panels[source_v][0]

            # Copy from source to all other panels
            for hidx, (hp_start, hp_end) in enumerate(horiz_panels):
                for vidx, (vp_start, vp_end) in enumerate(vert_panels):
                    if (hidx, vidx) == (source_h, source_v):
                        continue
                    for r in range(hp_start, hp_end + 1):
                        for c in range(vp_start, vp_end + 1):
                            rel_r = r - hp_start
                            src_r = h_start + rel_r
                            rel_c = c - vp_start
                            src_c = v_start + rel_c
                            g[r][c] = g[src_r][src_c]

        return g

